    const boss=g.enemies.find(e=>e.kind==='boss'&&e.hp>0);if(boss){ctx.fillStyle='#101820ee';ctx.fillRect(66,8,268,48);ctx.fillStyle='#f2d3a1';ctx.font='bold 14px system-ui';ctx.fillText(`${boss.finalBoss?'VEYR, HOLLOW KING':boss.bossType==='golem'?'STONE GOLEM':boss.bossType==='wisp'?'STORM WISP':'IRON WARDEN'} · ${Math.ceil(boss.hp)} / ${Math.ceil(boss.maxHp)} HP`,200,27);ctx.fillStyle='#4b3036';ctx.fillRect(78,36,244,9);ctx.fillStyle=boss.flash?'#fff':'#ec8d79';ctx.fillRect(78,36,244*Math.max(0,boss.hp)/boss.maxHp,9);}
    if(g.chargedFx>0){ctx.save();ctx.globalAlpha=g.chargedFx/.4;ctx.strokeStyle='#fff0b1';ctx.lineWidth=8;ctx.beginPath();ctx.arc(200,535,95+(1-g.chargedFx/.4)*35,Math.PI,Math.PI*2);ctx.stroke();ctx.restore();}
