   setHud({mode:g.mode,hp:g.hp,stamina:g.stamina,time:g.time,runSpeed:g.runSpeed,distance:g.distance,wave:g.wave,remaining:g.remaining,rest:g.rest,coins:g.coins,kills:g.kills,blocks:g.blocks,shield,shooting,broken:g.broken,notice:g.noticeTime>0?g.notice:''});frame=requestAnimationFrame(tick);
