 const down=(side:'left'|'right',e:React.PointerEvent<HTMLButtonElement>)=>{e.preventDefault();if(game.current.mode!=='playing')return;e.currentTarget.setPointerCapture(e.pointerId);if(side==='left')input.current.left.add(e.pointerId);else input.current.right.set(e.pointerId,performance.now());};
 const up=(side:'left'|'right',e:React.PointerEvent<HTMLButtonElement>,cancelled=false)=>{e.preventDefault();if(side==='left')input.current.left.delete(e.pointerId);else{const at=input.current.right.get(e.pointerId);input.current.right.delete(e.pointerId);if(!cancelled&&at!==undefined&&performance.now()-at<230)swing();}};
 const candidates=([
 ...skillNodes.filter(n=>(saved.skills?.[n.id]??0)<10&&(n.previous?(saved.skills?.[n.previous]??0)>=3:saved[n.branch]>=3)).map(n=>({name:n.name,cost:skillPrice(n.id,saved.skills?.[n.id]??0)})),
 ...(['sword','magic','shield'] as Branch[]).flatMap(branch=>saved[branch]<masteryCap?[{name:`${branch} rank ${saved[branch]+1}`,cost:costs[saved[branch]]}]:!saved[advanced[branch].key]?[{name:advanced[branch].name,cost:200}]:[]),
 ...((saved.unlocked??0)<20?[{name:weapons[(saved.unlocked??0)+1].name,cost:weapons[(saved.unlocked??0)+1].cost}]:[]),
 ...(['sword','magic','shield'] as GearKind[]).flatMap(kind=>{const gear=saved.gear??gearDefaults(saved.unlocked??0);return catalog[kind].flatMap((item,i)=>kind==='sword'&&i===21&&gear.sword[i]<0?[]:gear[kind][i]>=0&&gear[kind][i]<10?[{name:item.name+' upgrade '+(gear[kind][i]+1),cost:upgradePrice(kind,i,gear[kind][i])}]:gear[kind][i]<0&&(i===0||gear[kind][i-1]>=0)?[{name:item.name,cost:item.cost}]:[]);})
 ]).sort((a,b)=>a.cost-b.cost);const nextPurchase=candidates[0];
 return <main><div className="desktop-note"><span className="eyebrow">DESKTOP BALANCE · PHASE 06</span><h1>Runeblade</h1><p>A sword. A spell.<br/>How far can you run?</p><div className="key-hint">On desktop<br/><b>Space</b> Tap / hold to attack<br/><b>Shift</b> Hold to shield<br/><b>E</b> Throw shield<br/><b>Q</b> Lunge</div></div><section className="game" aria-label="Runeblade combat game">
 <header><div><span className="eyebrow">RUNEBLADE</span><span className="chapter">{regions[Math.floor((hud.wave-1)/5)%regions.length].name}</span><span className="region-progress">Region {Math.floor((hud.wave-1)/5)%10+1}/10 · Cycle {Math.floor((hud.wave-1)/50)+1}</span></div><button className="sound-button" aria-pressed={muted} onClick={toggleSound}>{muted?'Sound off':'Sound on'}</button><button className="icon-button" onClick={pause} disabled={hud.mode!=='playing'} aria-label="Pause game"><Pause size={20}/></button></header>
 <div className="stats"><div><span className="stat-label">VITALITY</span><div className="hearts" aria-label={`${hud.hp} of 5 health`}>{[1,2,3,4,5].map(n=><span className={n<=hud.hp?'full':''} key={n}>◆</span>)}</div></div><div className="time"><b>{hud.wave}</b><span className="stat-label">{hud.wave%5===0?'BOSS WAVE':'WAVE'}</span></div><div className="defeated"><b>{String(hud.kills).padStart(2,'0')}</b><span className="stat-label">DEFEATED</span></div></div>
 <div className="arena"><canvas ref={canvas} width="400" height="610" aria-label="Your sword-carrying hero runs forward as the road scrolls beneath him. Enemies approach from ahead."/><div className="feedback" aria-live="polite">{hud.mode==='playing'?hud.notice:''}</div>
 {hud.mode!=='playing'&&<div className={`overlay ${shop?'shop-open':''}`}><div className="start-card">{shop?<><span className="eyebrow">PREPARE FOR THE NEXT RUN</span><h2>Prepare for battle</h2><p>{saved.coins} coins available</p><button className="upgrade-entry back-run" onClick={()=>setShop(false)}>Back to run</button><Tabs defaultValue="skills" className="shop-tabs"><TabsList aria-label="Upgrade category"><TabsTrigger value="skills">Skills</TabsTrigger><TabsTrigger value="weapons">Armoury</TabsTrigger><TabsTrigger value="items">Items</TabsTrigger><TabsTrigger value="lore">Chronicle</TabsTrigger></TabsList><TabsContent value="skills"><div className="upgrade-list">{(['sword','magic','shield'] as Branch[]).map(branch=><div className="upgrade" key={branch}><strong>{branch==='sword'?'Sword mastery':branch==='magic'?'Arcane power':'Shield endurance'}</strong><span>Rank {saved[branch]} / {masteryCap} · {branch==='sword'?`+${(saved.sword*.5).toFixed(1)} damage to every sword`:branch==='magic'?`+${(saved.magic*.2).toFixed(1)} damage to every magic power`:`${shieldDrain(saved.shield).toFixed(1)} base stamina / second`}</span><button disabled={!loaded||saved[branch]>=masteryCap||saved.coins<costs[saved[branch]]} onClick={()=>buy(branch)}>{saved[branch]>=masteryCap?'Fully upgraded':`Upgrade · ${costs[saved[branch]]} coins`}</button><div className="advanced-skill"><strong>{advanced[branch].name}</strong><span>{advanced[branch].description}</span><button disabled={!loaded||saved[branch]<3||!!saved[advanced[branch].key]||saved.coins<200} onClick={()=>buyAdvanced(branch)}>{saved[advanced[branch].key]?'Unlocked':saved[branch]<3?'Requires rank 3':'Unlock skill · 200 coins'}</button></div></div>)}</div><SkillTree coins={saved.coins} ranks={saved.skills??{}} mastery={saved} onBuy={buySkill}/></TabsContent><TabsContent value="weapons"><Armoury gear={saved.gear??gearDefaults(saved.unlocked??0)} coins={saved.coins} swordEquipped={saved.equipped??0} onAction={gearAction}/></TabsContent><TabsContent value="items"><h3>Legendary equipment</h3><p>Choose up to three powers before your run. Purchases are permanent.</p><div className="legendary-slots">{[0,1,2].map(n=>{const item=legendaryItems.find(i=>i.id===saved.loadout?.[n]);return <div key={n} style={{borderColor:item?.color}}>{item?<><span style={{color:item.color}}>{item.icon}</span><b>{item.name}</b></>:<><span>＋</span><b>Empty slot</b></>}</div>;})}</div><p>{saved.loadout?.length??0} / 3 equipped · {saved.coins.toLocaleString()} coins</p><div className="legendary-list">{legendaryItems.map(item=>{const owned=saved.items?.includes(item.id),active=saved.loadout?.includes(item.id),full=(saved.loadout?.length??0)>=3;return <article key={item.id} style={{borderColor:item.color}}><span className="legendary-icon" style={{color:item.color}}>{item.icon}</span><h3>{item.name}</h3><p>{item.description}</p><button disabled={!owned?saved.coins<item.cost:!active&&full} onClick={()=>itemAction(item.id)}>{active?'Unequip':owned?full?'Three slots full':'Equip':`Acquire · ${item.cost.toLocaleString()} coins`}</button></article>;})}</div></TabsContent><TabsContent value="lore"><RelicJournal found={saved.relics??[]} complete={!!saved.storyComplete}/></TabsContent></Tabs></>:<><span className="crest"><Sword size={30}/></span><span className="eyebrow">{hud.mode==='ready'?'THE ENDLESS ROAD':hud.mode==='paused'?'TAKE A BREATH':'RUN ENDED'}</span><h2>{hud.mode==='ready'?'Run into battle.':hud.mode==='paused'?'Paused':'Rise again.'}</h2><p>{hud.mode==='ready'?'You are Caelan. Dead for a century. Returned to reclaim Asterfall from the Hollow King. Recover your lost relics and reach the Void Throne.':hud.mode==='paused'?'Your run is waiting for you.':`Wave ${hud.wave} reached · ${hud.kills} defeated · ${hud.coins} coins earned`}</p>{hud.mode==='lost'&&<><div className="run-summary"><div><b>{hud.wave}</b><span>Wave reached</span></div><div><b>{saved.bestWave??hud.wave}</b><span>Best wave</span></div><div><b>+{hud.coins}</b><span>Coins earned</span></div><div><b>{hud.blocks}</b><span>Blocks</span></div></div><div className="affordable"><strong>Next purchase</strong><p>{nextPurchase?`${nextPurchase.name} · ${nextPurchase.cost} coins${saved.coins>=nextPurchase.cost?' — affordable now':` — ${nextPurchase.cost-saved.coins} more needed`}`:'All skills and weapons unlocked.'}</p></div></>}{hud.mode==='ready'&&<div className="instructions"><span><Sword size={18}/> Tap right to slash</span><span><Sparkles size={18}/> Hold right to cast</span><span><Shield size={18}/> Hold left to block</span></div>}<button className="primary" disabled={!loaded} onClick={()=>hud.mode==='paused'?(game.current.mode='playing'):start()}>{hud.mode==='ready'?<Play size={18}/>:<RotateCcw size={18}/>} {hud.mode==='ready'?'Begin run':hud.mode==='paused'?'Resume run':'Try again'}</button><span className="footnote">{hud.mode==='ready'?'Archers join from wave 3. Block orange projectiles. Bosses fire a volley, then close in.':'Sword · Magic · Shield'}</span>{hud.mode!=='paused'&&<button className="upgrade-entry" onClick={()=>setShop(true)}>Upgrades · {saved.coins} coins</button>}</>}<span className="footnote" role="status">{saveMessage}</span></div></div>}
 </div><footer><div className="stamina-label"><span>{hud.broken?'SHIELD EXHAUSTED — RELEASE TO RECOVER':'SHIELD STAMINA'}</span><span>{Math.round(hud.stamina)}%</span></div><meter min="0" max="100" value={hud.stamina} aria-label="Shield stamina"/><div className="ability-row"><button className="throw-shield" disabled={hud.mode!=='playing'||game.current.throwWait>0||!!game.current.flying} onClick={throwShield}>Throw shield · {game.current.throwWait>0?Math.ceil(game.current.throwWait)+'s':'E / tap'}</button><button className="throw-shield" disabled={hud.mode!=='playing'||game.current.lungeWait>0||!!game.current.lunge} onClick={lunge}>Lunge · {game.current.lungeWait>0?Math.ceil(game.current.lungeWait)+'s':'Q / tap'}</button></div><div className="controls">{(['left','right'] as const).map(side=><button key={side} disabled={hud.mode!=='playing'} className={`combat ${side} ${(side==='left'?hud.shield:hud.shooting)?'active':''}`} onContextMenu={e=>e.preventDefault()} onPointerDown={e=>down(side,e)} onPointerUp={e=>up(side,e)} onPointerCancel={e=>up(side,e,true)} onLostPointerCapture={e=>up(side,e,true)} aria-label={side==='left'?'Hold for shield':'Tap for sword, hold for magical bolts'}>{side==='left'?<Shield size={26}/>:<Sword size={26}/>}<b>{side==='left'?'Shield':hud.shooting?'Casting':'Attack'}</b><span>{side==='left'?'HOLD TO BLOCK':'TAP SWORD · HOLD MAGIC'}</span></button>)}</div><div className="stage-label"><span>{Math.round(hud.runSpeed/125*100)}% PACE · </span>{saved.charged&&<span>{game.current.combo===3?'CHARGED STRIKE READY':`CHARGE ${game.current.combo}/3`} · </span>}{hud.rest>0?'NEXT WAVE APPROACHING':`${hud.remaining} INCOMING`} · {hud.coins} COINS</div></footer></section></main>;
